const datos = $input.first().json;

const mensaje = String(
  $('Recibir mensaje de WhatsApp1').first().json.body.Body || ''
).toLowerCase();

// Normalizar texto: elimina tildes y convierte a minúsculas
const normalizar = texto =>
  String(texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

const consulta = normalizar(mensaje);

// Fecha actual de Lima
const fechaActual = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Lima',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

// Obtener el primer valor disponible entre posibles nombres de columna
function obtenerValor(...nombres) {
  for (const nombre of nombres) {
    const valor = datos[nombre];

    if (valor !== undefined && valor !== null && String(valor).trim() !== '') {
      return valor;
    }
  }

  return '';
}

// Convertir fechas a YYYY-MM-DD
function convertirFecha(valor) {
  if (valor === undefined || valor === null || valor === '') {
    return null;
  }

  if (valor instanceof Date && !isNaN(valor.getTime())) {
    return new Intl.DateTimeFormat('en-CA', {
      timeZone: 'America/Lima',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).format(valor);
  }

  const texto = String(valor).trim();

  // Formato YYYY-MM-DD
  const iso = texto.match(/^(\d{4})-(\d{2})-(\d{2})/);

  if (iso) {
    return `${iso[1]}-${iso[2]}-${iso[3]}`;
  }

  // Formato DD/MM/YYYY o DD-MM-YYYY
  const latino = texto.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);

  if (latino) {
    const dia = latino[1].padStart(2, '0');
    const mes = latino[2].padStart(2, '0');

    return `${latino[3]}-${mes}-${dia}`;
  }

  // Número serial de Excel / Google Sheets
  if (/^\d+(\.\d+)?$/.test(texto)) {
    const numero = Number(texto);

    if (numero > 20000 && numero < 100000) {
      const fecha = new Date(
        Date.UTC(1899, 11, 30) + numero * 86400000
      );

      return fecha.toISOString().slice(0, 10);
    }
  }

  return null;
}

// Diferencia entre fechas en días
function diasEntre(fechaInicio, fechaFin) {
  const inicio = new Date(`${fechaInicio}T00:00:00Z`);
  const fin = new Date(`${fechaFin}T00:00:00Z`);

  return Math.round((fin - inicio) / 86400000);
}

// Definir campos informativos
const campos = [
  {
    patrones: /\b(estado|situacion)\b/,
    obtener: () => obtenerValor('Estado'),
    etiqueta: 'Estado'
  },
  {
    patrones: /\b(responsable|encargado)\b/,
    obtener: () => obtenerValor('Responsable'),
    etiqueta: 'Responsable'
  },
  {
    patrones: /\b(solicitante|solicito|quien solicito)\b/,
    obtener: () => obtenerValor('Solicitante'),
    etiqueta: 'Solicitante'
  },
  {
    patrones: /\b(fecha de ingreso|fecha ingreso)\b/,
    obtener: () => obtenerValor('Fecha ingreso'),
    etiqueta: 'Fecha de ingreso'
  },
  {
    patrones: /\b(prioridad actual)\b/,
    obtener: () => obtenerValor('Prioridad actual'),
    etiqueta: 'Prioridad actual'
  },
  {
    patrones: /\b(tecnologia)\b/,
    obtener: () => obtenerValor('Tecnología', 'Tecnologia'),
    etiqueta: 'Tecnología'
  },
  {
    patrones: /\b(descripcion)\b/,
    obtener: () => obtenerValor('Descripción', 'Descripcion'),
    etiqueta: 'Descripción'
  },
  {
    patrones: /\b(area)\b/,
    obtener: () => obtenerValor('Área', 'Area'),
    etiqueta: 'Área'
  },
  {
    patrones: /\b(actividad)\b/,
    obtener: () => obtenerValor('Actividad'),
    etiqueta: 'Actividad'
  }
];

// Identificar consultas relacionadas con la fecha límite
const consultaFecha =
  /\b(fecha limite|fecha de entrega|fecha de vencimiento|vencimiento|cuantos dias|dentro del plazo|fuera de plazo|a tiempo|ya paso|paso|vencio|vencida|vencido|atraso|atrasada|atrasado)\b/.test(consulta);

// Detectar campos solicitados
const solicitados = campos.filter(campo =>
  campo.patrones.test(consulta)
);

// Preparar respuesta
const respuesta = [
  `Actividad: ${datos.ID || 'No identificada'}`
];

for (const campo of solicitados) {
  const valor = campo.obtener();

  respuesta.push(
    `${campo.etiqueta}: ${valor !== '' ? valor : 'Sin información registrada'}`
  );
}

// Evaluar fecha límite cuando corresponda
if (consultaFecha) {
  const valorFecha = obtenerValor('Fecha límite', 'Fecha limite');
  const fechaLimite = convertirFecha(valorFecha);

  if (!valorFecha) {
    respuesta.push('Fecha límite: Sin información registrada');
  } else if (!fechaLimite) {
    respuesta.push(
      'Fecha límite: No fue posible interpretar el formato de la fecha registrada.'
    );
  } else {
    respuesta.push(`Fecha límite: ${valorFecha}`);

    const diferencia = diasEntre(fechaActual, fechaLimite);

    const estado = normalizar(obtenerValor('Estado'));

    if (estado === 'completada' || estado === 'completado') {
      respuesta.push(
        'Estado del plazo: La actividad está completada.'
      );
    } else if (diferencia < 0) {
      respuesta.push(
        `Estado del plazo: La fecha límite venció hace ${Math.abs(diferencia)} días.`
      );
    } else if (diferencia === 0) {
      respuesta.push(
        'Estado del plazo: La fecha límite es hoy.'
      );
    } else {
      respuesta.push(
        `Estado del plazo: La actividad está dentro del plazo. Faltan ${diferencia} días.`
      );
    }
  }
}

// Si no se identificó ningún dato
if (solicitados.length === 0 && !consultaFecha) {
  respuesta.push('No se identificó el dato solicitado.');
}

return [{
  json: {
    message: respuesta.join('\n'),
    parte: 1,
    total: 1
  }
}];

const datos = $input.first().json;

const texto = `
Actividad: ${datos.ID || 'No identificada'}

Recomendación IA:
${datos["Recomendación IA"] || 'No disponible'}

Prioridad recomendada:
${datos["Prioridad recomendada"] || 'No disponible'}

Riesgo por retraso:
${datos["Riesgo por retraso"] || 'No disponible'}

Siguiente acción:
${datos["Siguiente acción"] || 'No disponible'}
`.trim();

const limite = 1500;
const mensajes = [];
let restante = texto;

while (restante.length > limite) {
  let corte = restante.lastIndexOf('\n', limite);

  if (corte < limite * 0.5) {
    corte = restante.lastIndexOf(' ', limite);
  }

  if (corte < 1) {
    corte = limite;
  }

  mensajes.push(restante.slice(0, corte).trim());
  restante = restante.slice(corte).trim();
}

if (restante) {
  mensajes.push(restante);
}

return mensajes.map((mensaje, index) => ({
  json: {
    message: mensaje,
    parte: index + 1,
    total: mensajes.length
  }
}));

